#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <sched.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#define KC 192
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define KC 256
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define MCMAX 96
#define NCMAX 4096
#define MAXT 64
#define SPIN_LIMIT (1L << 22)

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Computes (or accumulates into) an mr x nr tile of C from packed A and B panels. */
static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

    for (int i = 0; i < mr; i++) {
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);
        __builtin_prefetch(c + (size_t)i * ldc + NR - 1, 1, 3);
    }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)b;
        vf b1 = *(const vf *)(b + VW);
#define STEP(i) { float t = a[i]; c##i##_0 += t * b0; c##i##_1 += t * b1; }
        ROWS(STEP)
#undef STEP
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (acc) {
#define ACC(i) { float *p = c + (size_t)(i) * ldc; \
                 stu(p, ldu(p) + c##i##_0); stu(p + VW, ldu(p + VW) + c##i##_1); }
            ROWS(ACC)
#undef ACC
        } else {
#define ST(i) { float *p = c + (size_t)(i) * ldc; stu(p, c##i##_0); stu(p + VW, c##i##_1); }
            ROWS(ST)
#undef ST
        }
    } else {
        float tmp[MR][NR];
#define TMP(i) { memcpy(&tmp[i][0], &c##i##_0, sizeof(vf)); memcpy(&tmp[i][VW], &c##i##_1, sizeof(vf)); }
        ROWS(TMP)
#undef TMP
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

/* Packs an mc x kc block of A into MR-row panels, zero-padding the last one. */
static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *d = Ap + (size_t)ip * kc;
        const float *s = A + (size_t)(i0 + ip) * n + p0;
        if (rows == MR) {
            for (int k = 0; k < kc; k++) {
#pragma GCC unroll 12
                for (int r = 0; r < MR; r++) d[r] = s[(size_t)r * n + k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < rows; r++) d[r] = s[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

/* Packs rows [kb, ke) of the kc x nc block of B at (p0, j0) into NR-wide panels. */
static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc,
                   int kb, int ke, float *Bp)
{
    for (int k = kb; k < ke; k++) {
        const float *s = B + (size_t)(p0 + k) * n + j0;
        float *d = Bp + (size_t)k * NR;
        int jp = 0;
        for (; jp + NR <= nc; jp += NR)
            memcpy(d + (size_t)jp * kc, s + jp, NR * sizeof(float));
        if (jp < nc) {
            float *dd = d + (size_t)jp * kc;
            int c = nc - jp;
            memcpy(dd, s + jp, (size_t)c * sizeof(float));
            memset(dd + c, 0, (size_t)(NR - c) * sizeof(float));
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    float *Bp[2];
    int n, nt, gm, gn;
    int kcb, ncb;
    int bar_count, bar_gen;
} job_t;

static job_t g_job;
static float g_Ap[MAXT][MCMAX * KC] __attribute__((aligned(64)));

static void barrier_wait(job_t *j)
{
    int g = __atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE);
    if (__atomic_add_fetch(&j->bar_count, 1, __ATOMIC_ACQ_REL) == j->nt) {
        __atomic_store_n(&j->bar_count, 0, __ATOMIC_RELAXED);
        __atomic_store_n(&j->bar_gen, g + 1, __ATOMIC_RELEASE);
    } else {
        long spins = 0;
        while (__atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE) == g) {
            cpu_relax();
            if (++spins > (1L << 20)) { sched_yield(); spins = 0; }
        }
    }
}

static void run(int tid)
{
    job_t *j = &g_job;
    const float *A = j->A, *B = j->B;
    float *C = j->C;
    int n = j->n, nt = j->nt, gm = j->gm, gn = j->gn;
    int kcb = j->kcb, ncb = j->ncb;
    int rg = tid / gn, cg = tid % gn;
    float *Ap = g_Ap[tid];

    int units = (n + MR - 1) / MR;
    int r0 = (int)((long)units * rg / gm) * MR;
    int r1 = (int)((long)units * (rg + 1) / gm) * MR;
    if (r1 > n) r1 = n;
    int rows = r1 - r0;
    int mstep = MCMAX;
    if (rows > 0) {
        int nic = (rows + MCMAX - 1) / MCMAX;
        mstep = (rows + nic - 1) / nic;
        mstep = (mstep + MR - 1) / MR * MR;
    }

    int it = 0;
    for (int jc = 0; jc < n; jc += ncb) {
        int nc = n - jc < ncb ? n - jc : ncb;
        int np = (nc + NR - 1) / NR;
        int p0 = (int)((long)np * cg / gn), p1 = (int)((long)np * (cg + 1) / gn);
        for (int pc = 0; pc < n; pc += kcb, it++) {
            int kc = n - pc < kcb ? n - pc : kcb;
            int acc = pc != 0;
            float *Bp = j->Bp[it & 1];

            int kb = (int)((long)kc * tid / nt), ke = (int)((long)kc * (tid + 1) / nt);
            pack_b(B, n, pc, kc, jc, nc, kb, ke, Bp);
            if (nt > 1) barrier_wait(j);

            for (int ic = r0; ic < r1; ic += mstep) {
                int mc = r1 - ic < mstep ? r1 - ic : mstep;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                for (int p = p0; p < p1; p++) {
                    int jr = p * NR;
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)jr * kc;
                    float *cc = C + (size_t)ic * n + jc + jr;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp, cc + (size_t)ir * n, n, mr, nr, acc);
                    }
                }
            }
        }
    }
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
            } else {
                pthread_mutex_lock(&g_mu);
                while (__atomic_load_n(&g_gen, __ATOMIC_ACQUIRE) == seen)
                    pthread_cond_wait(&g_cv, &g_mu);
                pthread_mutex_unlock(&g_mu);
                spins = 0;
            }
        }
        seen = g;
        if (tid < g_job.nt) run(tid);
        __atomic_sub_fetch(&g_remaining, 1, __ATOMIC_ACQ_REL);
    }
    return NULL;
}

static int detect_threads(void)
{
    int n = 0;
#ifdef __linux__
    cpu_set_t cs;
    if (sched_getaffinity(0, sizeof cs, &cs) == 0) n = CPU_COUNT(&cs);
#endif
    if (n <= 0) {
        long c = sysconf(_SC_NPROCESSORS_ONLN);
        n = c > 0 ? (int)c : 1;
    }
    int smt = 1;
#ifdef __linux__
    FILE *f = fopen("/sys/devices/system/cpu/cpu0/topology/thread_siblings_list", "r");
    if (f) {
        char buf[256];
        if (fgets(buf, sizeof buf, f)) {
            int count = 0;
            char *p = buf, *e;
            for (;;) {
                long a = strtol(p, &e, 10);
                if (e == p) break;
                long b = a;
                if (*e == '-') b = strtol(e + 1, &e, 10);
                count += (int)(b - a + 1);
                if (*e != ',') break;
                p = e + 1;
            }
            if (count > 1) smt = count;
        }
        fclose(f);
    }
#endif
    if (smt > 1 && n >= smt) n /= smt;
    if (n < 1) n = 1;
    if (n > MAXT) n = MAXT;
    return n;
}

static void pool_init(void)
{
    int hw = detect_threads();
    int created = 0;
    for (int t = 1; t < hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
    }
    g_pool = created;
}

static float *g_Bbuf;
static size_t g_Bcap;

static float *ensure(float **buf, size_t *cap, size_t nfloats)
{
    if (nfloats > *cap) {
        free(*buf);
        size_t bytes = (nfloats * sizeof(float) + 63) / 64 * 64;
        *buf = aligned_alloc(64, bytes);
        *cap = *buf ? nfloats : 0;
    }
    return *buf;
}

static void naive(const float *A, const float *B, float *C, int n)
{
    for (int i = 0; i < n; i++) {
        float *c = C + (size_t)i * n;
        for (int jj = 0; jj < n; jj++) c[jj] = 0.0f;
        for (int k = 0; k < n; k++) {
            float a = A[(size_t)i * n + k];
            const float *b = B + (size_t)k * n;
            for (int jj = 0; jj < n; jj++) c[jj] += a * b[jj];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (g_pool < 0) pool_init();

    int nt = g_pool + 1;
    if (n < 128) nt = 1;

    /* Balanced block sizes: no short trailing k or column block. */
    int nkb = (n + KC - 1) / KC;
    int kcb = (n + nkb - 1) / nkb;
    int njb = (n + NCMAX - 1) / NCMAX;
    int ncb = (n + njb - 1) / njb;
    ncb = (ncb + NR - 1) / NR * NR;

    size_t bsz = (size_t)KC * ncb;
    float *Bbuf = ensure(&g_Bbuf, &g_Bcap, 2 * bsz);
    if (!Bbuf) { naive(A, B, C, n); return; }

    /* Thread grid: prefer splitting rows; split columns when rows run short. */
    int units = (n + MR - 1) / MR;
    int gm = 1, gn = nt;
    for (int g = nt; g >= 1; g--) {
        if (nt % g == 0 && units / g >= 8) { gm = g; gn = nt / g; break; }
    }
    int np = (ncb + NR - 1) / NR;
    if (gn > np) { gn = np; nt = gm * gn; }
    if (nt < 1) { nt = 1; gm = 1; gn = 1; }

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C;
    j->Bp[0] = Bbuf; j->Bp[1] = Bbuf + bsz;
    j->n = n; j->nt = nt; j->gm = gm; j->gn = gn;
    j->kcb = kcb; j->ncb = ncb;
    j->bar_count = 0;

    if (nt == 1) {
        run(0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
